    /// <summary>Resolves this program's uniform slots against a built pipeline's reflection.</summary>
    public readonly struct LineParameters
    {
        internal LineParameters(ShaderReflection reflection)
        {
            LightViewProj0 = SlotOf(reflection, "LightViewProj0");
            LightViewProj1 = SlotOf(reflection, "LightViewProj1");
            LightViewProj2 = SlotOf(reflection, "LightViewProj2");
            DepthBias = SlotOf(reflection, "DepthBias");
