            IsFullbright = SlotOf(reflection, "IsFullbright");
            UseBaseColor = SlotOf(reflection, "UseBaseColor");
            BaseColor = SlotOf(reflection, "BaseColor");
            FogColor = SlotOf(reflection, "FogColor");
            FogDistance = SlotOf(reflection, "FogDistance");
            FogLogDensity = SlotOf(reflection, "FogLogDensity");
            EnvironmentLight = SlotOf(reflection, "EnvironmentLight");
            CameraPosition = SlotOf(reflection, "CameraPosition");
            Alpha = SlotOf(reflection, "Alpha");
            Expand = SlotOf(reflection, "Expand");
            RandomFloat = SlotOf(reflection, "RandomFloat");
            Darken = SlotOf(reflection, "Darken");
            ChargedBlinkAmount = SlotOf(reflection, "ChargedBlinkAmount");
            HalfThickness = SlotOf(reflection, "HalfThickness");
            Resolution = SlotOf(reflection, "Resolution");
            DistantOutlineDistanceFalloffWithCutoffMask = SlotOf(reflection, "DistantOutlineDistanceFalloffWithCutoffMask");
            DistantOutlineClassicCutoffMask = SlotOf(reflection, "DistantOutlineClassicCutoffMask");
            DistantOutlineDistanceFalloffMask = SlotOf(reflection, "DistantOutlineDistanceFalloffMask");
            OutlineClassicCutoffDistance = SlotOf(reflection, "OutlineClassicCutoffDistance");
            OutlineFalloffStartDistance = SlotOf(reflection, "OutlineFalloffStartDistance");
            OutlineFalloffCutoffDistance = SlotOf(reflection, "OutlineFalloffCutoffDistance");
            OutlineFalloffLinearFadeStartDistance = SlotOf(reflection, "OutlineFalloffLinearFadeStartDistance");
            OutlineFalloffLinearFadeStartThickness = SlotOf(reflection, "OutlineFalloffLinearFadeStartThickness");
            OutlineFalloffInverseLinearFadeLength = SlotOf(reflection, "OutlineFalloffInverseLinearFadeLength");
        }

        public int LightViewProj0 { get; }
        public int LightViewProj1 { get; }
        public int LightViewProj2 { get; }
        public int DepthBias { get; }
        public int NumCascades { get; }
        public int LightDirection { get; }
        public int View { get; }
        public int Projection { get; }
        public int ViewProj { get; }
        public int SnapColor { get; }
        public int IsFullbright { get; }
        public int UseBaseColor { get; }
        public int BaseColor { get; }
        public int FogColor { get; }
        public int FogDistance { get; }
        public int FogLogDensity { get; }
        public int EnvironmentLight { get; }
        public int CameraPosition { get; }
        public int Alpha { get; }
        public int Expand { get; }
        public int RandomFloat { get; }
        public int Darken { get; }
